Use event-type routing. MetroWave webhook payloads are envelope-based.

Example:

```json
{
  "event_id": "evt_01J4Z8N7P6",
  "event_type": "appointment.scheduled",
  "occurred_at": "2026-08-02T16:24:18Z",
  "account_id": "ENT-44019",
  "resource": {
    "type": "broadband_order",
    "id": "ord_928311"
  },
  "data": {
    "appointment_window_start": "2026-08-06T13:00:00Z",
    "appointment_window_end": "2026-08-06T17:00:00Z"
  }
}
```

**Idempotency key:** use `event_id`. If your downstream requires resource-level ordering, partition Kafka by `resource.id`.

Here’s an Express-compatible verification example using a raw body buffer:

```js
import crypto from "node:crypto";

function verifyMetroWaveSignature({ rawBody, timestamp, signature, secret }) {
  if (!timestamp || !signature) return false;

  const skewMs = Math.abs(Date.now() - Date.parse(timestamp));
  if (Number.isNaN(skewMs) || skewMs > 5 * 60 * 1000) return false;

  const signedPayload = Buffer.concat([
    Buffer.from(timestamp, "utf8"),
    Buffer.from(".", "utf8"),
    rawBody
  ]);

  const expected = crypto
    .createHmac("sha256", secret)
    .update(signedPayload)
    .digest("hex");

  const received = signature.replace(/^v1=/, "");

  return crypto.timingSafeEqual(
    Buffer.from(expected, "hex"),
    Buffer.from(received, "hex")
  );
}
```

Important: validate signature **before** JSON parsing if possible.

Correct — good catch. Use a length check first.

```js
const expectedBuf = Buffer.from(expected, "hex");
const receivedBuf = Buffer.from(received, "hex");

if (expectedBuf.length !== receivedBuf.length) {
  return false;
}

return crypto.timingSafeEqual(expectedBuf, receivedBuf);
```

Also reject non-hex values before conversion if you want stricter handling:

```js
if (!/^[a-f0-9]{64}$/i.test(received)) return false;
```
